  $('active-filters').hidden=state.view!=='map';$('active-filters').innerHTML=[state.line!=='all'?routeName(state.line):'',state.pref!=='all'?PREFECTURES[state.pref]+'の公表分':'',state.favorites?'保存した駅':'',state.q?`検索：${state.q}`:''].filter(Boolean).map(t=>`<span>${escapeHtml(t)}</span>`).join('');
  $('map-view').dataset.panel=state.panel;document.querySelectorAll('[data-panel]').forEach(b=>{if(b.tagName==='BUTTON')b.setAttribute('aria-pressed',String(b.dataset.panel===state.panel))});
  if(state.view==='map'){resultList();$('map-selection').innerHTML=filtered().length?preview():'<div class="empty"><b>条件に合う駅がありません</b><p>絞り込み条件を減らしてください。</p><button data-reset>条件をクリア</button></div>';}
  if(state.view==='profile')profile();if(state.view==='compare')$('compare').innerHTML=compareView();if(state.view==='line')lineView();
  if(state.view==='numbers'){$('numbers').innerHTML=numbersView();if($('district-results'))renderDistrictRows();if($('cafe-results'))renderCafeRows();}
  if(state.view==='sources')sourcesView();
  $('compare-tray').hidden=!state.pins.length||['compare','sources'].includes(state.view);$('compare-tray').innerHTML=`<div><b>${state.pins.length}駅を比較に選択</b><span>${state.pins.map(id=>escapeHtml(data.stations.find(s=>s.id===id)?.name)).join('・')}</span></div><button data-view="compare" data-station-comparison class="primary">比較する →</button><button data-clear-pins aria-label="比較選択をクリア">×</button>`;
  $('map-selection').hidden=state.view!=='map';
  if(['map','profile','line'].includes(state.view)){const slot=state.view==='profile'?'profile-map-slot':state.view==='line'?'line-map-slot':'explore-map-slot';if($('map-card').parentElement!==$(slot))$(slot).append($('map-card'));requestAnimationFrame(()=>{map?.resize();const key=[state.view,state.line,state.q,state.pref,state.available,state.sort,state.panel,state.favorites?favorites.join(','):'',state.view==='profile'?selectedStation().id:''].join('|');if(key!==lastMapKey&&!(state.view==='map'&&state.panel==='list'&&matchMedia('(max-width: 800px)').matches)){fitMap();lastMapKey=key;}});}
  updateMap();bindDynamic();
  if(focusId&&$(focusId)&&document.activeElement!==$(focusId)){$(focusId).focus({preventScroll:true});if(selection!==null&&typeof $(focusId).setSelectionRange==='function'&&['search','text'].includes($(focusId).type))$(focusId).setSelectionRange(selection,selection);}
