 let filtersCollapsed=matchMedia('(max-width: 700px)').matches;
 function bindDynamic(){
  if($('compare-add'))$('compare-add').onchange=e=>{if(e.target.value)pin(e.target.value)};
  if($('line-pick'))$('line-pick').onchange=e=>change({line:e.target.value,station:'',page:1});
  if($('district-query'))$('district-query').oninput=e=>{districtLimit=30;change({regionQuery:e.target.value},{replace:true})};
  if($('district-pref'))$('district-pref').onchange=e=>{districtLimit=30;change({regionPref:e.target.value},{replace:true})};
  if($('cafe-query'))$('cafe-query').oninput=e=>{cafeLimit=30;change({regionQuery:e.target.value},{replace:true})};
  if($('district-more'))$('district-more').onclick=()=>{districtLimit+=30;renderDistrictRows()};if($('cafe-more'))$('cafe-more').onclick=()=>{cafeLimit+=30;renderCafeRows()};
  if($('profile-back'))$('profile-back').onclick=()=>{location.hash=profileReturnHash&&parseState(profileReturnHash,data).view!=='profile'?profileReturnHash:serializeExplorerState({...state,view:'map'})};
  if($('share-station'))$('share-station').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);$('share-station').textContent='コピーしました';notify('駅プロフィールのリンクをコピーしました')}catch{$('share-station').textContent='アドレス欄のURLを共有してください';notify('アドレス欄のURLから共有できます')}};
 }
 document.addEventListener('click',e=>{
  const b=e.target.closest('button,a[data-profile-section]');if(!b||b.disabled)return;const d=b.dataset;
  if(d.profileSection){e.preventDefault();$(d.profileSection)?.scrollIntoView({behavior:'smooth',block:'start'});return;}
  if(d.definition){sourceReturnHash=location.hash;change({view:'sources'});setTimeout(()=>$('def-'+d.definition)?.scrollIntoView({block:'center'}),0);return;}
  if(d.favorite){setFavorite(d.favorite);return;}if(d.pin){pin(d.pin);return;}if('clearPins'in d){change({pins:[]});return;}
  if(d.profile){openProfile(d.profile);return;}if(d.station){if(state.panel==='list'&&matchMedia('(max-width: 800px)').matches)openProfile(d.station);else selectStation(d.station);return;}
  if(d.theme){change({theme:d.theme,columns:THEMES[d.theme].columns,sort:THEMES[d.theme].metric,dir:'desc',page:1});return;}
  if(d.sort){change({sort:d.sort,dir:state.sort===d.sort&&state.dir==='desc'?'asc':'desc',page:1});return;}
  if(d.panel){change({panel:d.panel});return;}if(d.page){change({page:Number(d.page)});return;}if('reset'in d){reset();return;}
  if(d.compareMode){change({compareMode:d.compareMode});return;}
  if(d.compare){const c=[...state.compare],id=d.compare;if(c.includes(id)){if(c.length<=2){$('compare-feedback').textContent='比較は2沿線以上を選択してください。';return;}c.splice(c.indexOf(id),1)}else{if(c.length>=4){$('compare-feedback').textContent='比較は4沿線までです。1沿線を外してください。';return;}c.push(id)}change({compare:c});return;}
  if('lineCompare'in d){const id=effectiveLine().id;change({view:'compare',compareMode:'lines',compare:[id,...routes.map(r=>r.id).filter(x=>x!==id).slice(0,1)]});return;}
  if(d.detail){change({view:'numbers',detail:d.detail,regionQuery:'',regionPref:'all'});return;}
  if(d.view){if(d.view==='sources')sourceReturnHash=location.hash;if(d.view==='profile'){openProfile(selectedStation().id);return;}change({view:d.view,...('stationComparison'in d?{compareMode:'stations'}:{})});window.scrollTo({top:0,behavior:'auto'});}
 });
 document.addEventListener('change',e=>{if(e.target.dataset.column){const k=e.target.dataset.column,columns=e.target.checked?[...state.columns,k]:state.columns.filter(x=>x!==k);if(!columns.length){e.target.checked=true;notify('指標を1つ以上選んでください');return;}change({columns});}});
