 $('download-csv').onclick=()=>{const keys=state.columns,rows=filtered(),text='\uFEFF'+[['駅ID','駅名','事業者','区画コード',...keys.flatMap(k=>[metricInfo(k).label,`${k}_単位`,`${k}_年次`,`${k}_集計範囲`,`${k}_状態`])],...rows.map(s=>[s.id,s.name,s.operator,s.meshCode,...keys.flatMap(k=>[value(s,k),metricInfo(k).unit,metricInfo(k).year,metricInfo(k).scope,value(s,k)===null?missingReason(data,studentData,s,k):metricInfo(k).kind])])].map(r=>r.map(csvEscape).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='ekimachi-observations.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
